  let output = '\n';
  output += useUnicode ? '\u{1F4AD} Memory Retrieved (Fallback)\n' : '=== Memory Retrieved (Fallback) ===\n';
  output += divider + '\n';

  for (let i = 0; i < memories.length; i++) {
